165	/** Sends e-mails to guests. Every e-mail sent is kept in the list of sent messages. */
166	public final class EmailSender {
167	
168	    private final SentMessages sentMessages;
169	
170	    public EmailSender(SentMessages sentMessages) {
171	        this.sentMessages = sentMessages;
172	    }
173	
174	    public Message send(String to, String subject, String body) {
175	        return sentMessages.add("EMAIL", to, subject, body);
176	    }
177	}
