181	}
182	package hotel.messages;
183	
184	import java.util.ArrayList;
185	import java.util.List;
186	
187	/** Every message the inn sent, so the front desk can check what each guest received. */
188	public final class SentMessages {
189	
190	    private final List<Message> messages = new ArrayList<>();
191	
192	    synchronized Message add(String channel, String to, String subject, String body) {
193	        Message message = new Message(messages.size() + 1L, channel, to, subject, body);
194	        messages.add(message);
195	        return message;
196	    }
197	
198	    public synchronized List<Message> all() {
199	        return new ArrayList<>(messages);
200	    }
201	}
