207	import hotel.reports.RevenueReport;
208	import hotel.reservations.PriceCalculator;
209	import hotel.reservations.ReservationService;
210	import hotel.reservations.ReservationStore;
211	import hotel.rooms.Rooms;
212	import hotel.web.HttpApi;
213	import io.javalin.Javalin;
214	
215	/** Puts the inn's pieces together and runs the HTTP server. */
216	public final class Hotel {
217	
218	    private final Javalin server;
219	
220	    public Hotel() {
221	        Rooms rooms = new Rooms();
222	        ReservationStore store = new ReservationStore();
223	        SentMessages sentMessages = new SentMessages();
224	        ReservationService reservations =
225	                new ReservationService(rooms, store, new PriceCalculator(), new EmailSender(sentMessages));
226	        HttpApi api = new HttpApi(
227	                rooms, reservations, sentMessages, new OccupancyReport(rooms, store), new RevenueReport(store));
228	        this.server = api.server();
229	    }
230	
231	    /** Starts listening; port 0 picks a free port. Returns the port in use. */
232	    public int start(int port) {
233	        server.start(port);
234	        return server.port();
235	    }
236	
237	    public void stop() {
238	        server.stop();
239	    }
240	
241	    public static void main(String[] args) {
242	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
243	        new Hotel().start(port);
244	    }
245	}

